import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { App } from "./App";
import "./styles.css";

const root = document.getElementById("root");

if (!root) {
  throw new Error("Root element was not found.");
}

createRoot(root).render(
  <StrictMode>
    <App />
  </StrictMode>
);

:root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #edf4ff;
  background: #06111d;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}

button,
input {
  font: inherit;
}

button {
  border: 1px solid #24425e;
  border-radius: 6px;
  background: #102235;
  color: #eef6ff;
  padding: 8px 12px;
}

button:not(:disabled) {
  cursor: pointer;
}

button:not(:disabled):hover {
  border-color: #2f7bdc;
  background: #16314c;
}

button:disabled {
  opacity: 0.42;
  cursor: default;
}

code {
  color: #9ac7ff;
}

.studio-shell {
  display: grid;
  grid-template-columns: 214px minmax(0, 1fr);
  width: 100%;
  height: 100%;
  background:
    radial-gradient(circle at 45% 0%, rgb(10 52 83 / 18%), transparent 35%),
    #07111c;
}

.studio-sidebar {
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-right: 1px solid #153651;
  background:
    linear-gradient(180deg, #0b1a2a 0%, #081421 100%);
}

.sidebar-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 72px;
  padding: 13px 14px;
  border-bottom: 1px solid #16334d;
}

.brand-logo {
  display: block;
  flex: 0 0 auto;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  object-fit: contain;
  box-shadow: 0 6px 20px rgb(255 112 24 / 16%);
}

.sidebar-brand div:last-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.sidebar-brand strong {
  font-size: 13px;
}

.sidebar-brand span {
  overflow: hidden;
  color: #6f8ca7;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 14px 10px;
}

.nav-item {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  width: 100%;
  border-color: transparent;
  background: transparent;
  padding: 10px 11px;
  text-align: left;
}

.nav-item.active {
  border-color: #1f79e5;
  background: linear-gradient(90deg, #0967e7, #0873f5);
  box-shadow: 0 8px 24px rgb(3 105 234 / 18%);
}

.nav-icon {
  color: #b6cce0;
  font-size: 16px;
  text-align: center;
}

.nav-check {
  color: #5fe083;
  font-weight: 800;
}

.sidebar-footer {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-top: auto;
  padding: 14px;
  border-top: 1px solid #16334d;
  color: #65829c;
  font-size: 10px;
}

.studio-main {
  display: grid;
  grid-template-rows: 42px minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
}

.studio-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 18px;
  border-bottom: 1px solid #153651;
  background: #071522;
}

.topbar-tagline {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #7a9ab9;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
}

.topbar-tagline b {
  color: #294d70;
}

.topbar-state {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #82a0ba;
  font-size: 11px;
}

.state-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #52d874;
  box-shadow: 0 0 12px rgb(82 216 116 / 50%);
}

.studio-content {
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.global-error {
  position: absolute;
  z-index: 50;
  top: 52px;
  right: 18px;
  max-width: 420px;
  padding: 10px 12px;
  border: 1px solid #8e3f47;
  border-radius: 7px;
  background: #331a20;
  color: #ffc4ca;
  font-size: 12px;
  box-shadow: 0 12px 32px rgb(0 0 0 / 28%);
}

.page-shell {
  height: 100%;
  overflow: auto;
  padding: 34px 42px 48px;
}

.page-title {
  max-width: 820px;
  margin-bottom: 28px;
}

.page-title.compact {
  margin-bottom: 24px;
}

.eyebrow,
.card-kicker {
  color: #489dff;
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.15em;
}

.page-title h1 {
  margin: 8px 0 9px;
  color: #f2f7fc;
  font-size: clamp(25px, 2.2vw, 38px);
  line-height: 1.08;
}

.page-title p {
  max-width: 720px;
  margin: 0;
  color: #7f9ab4;
  font-size: 13px;
  line-height: 1.6;
}

.home-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  max-width: 1100px;
}

.home-card,
.setup-card,
.info-card,
.placeholder-card {
  border: 1px solid #173c5c;
  border-radius: 10px;
  background:
    linear-gradient(155deg, rgb(16 43 67 / 96%), rgb(8 25 40 / 96%));
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 2%);
}

.home-card {
  display: flex;
  flex-direction: column;
  min-height: 230px;
  padding: 22px;
}

.home-card.accent-card {
  border-color: #1c67a4;
  background:
    linear-gradient(155deg, rgb(13 61 101 / 96%), rgb(8 28 45 / 96%));
}

.home-card h2,
.setup-card h2 {
  margin: 10px 0 8px;
  font-size: 18px;
}

.home-card p,
.setup-card p,
.info-card p {
  margin: 0 0 20px;
  color: #87a0b7;
  font-size: 12px;
  line-height: 1.58;
}

.home-card button {
  margin-top: auto;
}

.primary-button {
  border-color: #0875f5;
  background: linear-gradient(180deg, #0c7dff, #0667e8);
  font-weight: 720;
}

.primary-button:not(:disabled):hover {
  background: linear-gradient(180deg, #1a88ff, #0b70f0);
}

.primary-button.wide {
  width: 100%;
}

.wide {
  width: 100%;
}

.danger-action {
  border-color: #8f2f39;
  background: linear-gradient(180deg, #7a2630, #5d1d25);
  color: #ffe8ea;
  font-weight: 700;
}

.danger-action:not(:disabled):hover {
  background: linear-gradient(180deg, #922f3a, #6e222b);
}

.status-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  max-width: 1100px;
  margin-top: 18px;
  overflow: hidden;
  border: 1px solid #173852;
  border-radius: 8px;
  background: #173852;
}

.status-strip div {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 13px 15px;
  background: #0a1927;
}

.status-strip span {
  color: #6586a2;
  font-size: 10px;
  text-transform: uppercase;
}

.status-strip strong {
  font-size: 12px;
}

.setup-grid {
  display: grid;
  grid-template-columns: minmax(360px, 620px) minmax(250px, 340px);
  gap: 18px;
  align-items: start;
  max-width: 1000px;
}

.setup-card,
.info-card {
  padding: 24px;
}

.setup-card.centered {
  max-width: 620px;
}

.folder-illustration {
  display: grid;
  place-items: center;
  width: 64px;
  height: 52px;
  margin: 0 auto 8px;
  color: #ffb33d;
  font-size: 42px;
}

.setup-card h2,
.setup-card p {
  text-align: center;
}

.path-field {
  min-height: 42px;
  margin: 16px 0 12px;
  padding: 11px 12px;
  overflow: hidden;
  border: 1px solid #1c496c;
  border-radius: 6px;
  background: #071522;
  color: #a8bfd3;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.info-card h3 {
  margin: 0 0 12px;
  color: #8dc0ff;
  font-size: 14px;
}

.status-message,
.selected-map-card {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-top: 18px;
  padding: 13px;
  border: 1px solid #173d5c;
  border-radius: 7px;
  background: #081827;
  font-size: 11px;
}

.status-message span,
.selected-map-card span {
  color: #7591aa;
}

.status-message.success strong {
  color: #5ddd81;
}

.selected-map-card button {
  margin-top: 9px;
}

.placeholder-card {
  display: flex;
  flex-direction: column;
  gap: 7px;
  max-width: 650px;
  padding: 22px;
}

.placeholder-card span {
  color: #7892aa;
  font-size: 12px;
}

.map-editor {
  display: grid;
  grid-template-rows: 38px 30px 42px minmax(0, 1fr) 26px;
  height: 100%;
  min-height: 0;
  background: #06101a;
}

.editor-titlebar {
  display: flex;
  align-items: center;
  padding: 0 12px;
  border-bottom: 1px solid #173650;
  background: #091725;
  font-size: 12px;
}

.editor-titlebar > div {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
}

.map-open-indicator {
  color: #70d88b;
  font-size: 10px;
}

.editor-menubar,
.editor-toolbar {
  display: flex;
  align-items: center;
  border-bottom: 1px solid #173650;
  background: #0a1928;
}

.editor-menubar {
  padding: 0 7px;
}

.editor-menubar button {
  height: 100%;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 0 8px;
  color: #b4c5d5;
  font-size: 10px;
  opacity: 1;
}

.editor-menubar button:disabled {
  color: #b4c5d5;
  opacity: 1;
}

.editor-toolbar {
  gap: 5px;
  padding: 0 8px;
}

.tool {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  padding: 0;
  border-radius: 5px;
  font-size: 15px;
}

.tool.active {
  border-color: #1682ff;
  background: #096de2;
}

.toolbar-separator {
  width: 1px;
  height: 22px;
  margin: 0 5px;
  background: #21415e;
}

.toolbar-chip {
  padding: 6px 9px;
  border: 1px solid #1d405e;
  border-radius: 5px;
  background: #0d2032;
  color: #92aec7;
  font-size: 10px;
}

.toolbar-spacer {
  flex: 1;
}

.secondary-action {
  padding: 6px 9px;
  font-size: 10px;
}

.editor-grid {
  display: grid;
  grid-template-columns: 225px minmax(0, 1fr) 318px;
  min-width: 0;
  min-height: 0;
}

.map-explorer,
.object-inspector {
  min-height: 0;
  overflow: auto;
  background: #081521;
}

.map-explorer {
  display: grid;
  grid-template-rows: 34px minmax(0, 1fr) 42px;
  border-right: 1px solid #173650;
}

.object-inspector {
  border-left: 1px solid #173650;
}

.explorer-tabs,
.inspector-tabs {
  display: flex;
  border-bottom: 1px solid #173650;
}

.explorer-tabs button,
.inspector-tabs button {
  flex: 1;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 8px 5px;
  color: #718ba3;
  font-size: 10px;
}

.explorer-tabs button.active,
.inspector-tabs button.active {
  background: #0d6fea;
  color: white;
}

.explorer-tree {
  padding: 9px 7px;
}

.tree-root,
.tree-node {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) auto;
  align-items: center;
  gap: 5px;
  min-height: 31px;
  padding: 5px 7px;
  border-radius: 5px;
  color: #a8bdd0;
  font-size: 11px;
}

.tree-root {
  margin-bottom: 4px;
  color: #e1ebf4;
}

.tree-node.active {
  background: #0870e8;
  color: #fff;
}

.tree-node.disabled {
  color: #4f6a82;
}

.tree-node strong {
  font-size: 10px;
}

.tree-node small {
  color: #56718a;
  font-size: 8px;
}

.explorer-search {
  padding: 7px;
  border-top: 1px solid #173650;
}

.explorer-search input {
  width: 100%;
  height: 28px;
  border: 1px solid #1a405f;
  border-radius: 5px;
  background: #07131f;
  color: #9db4c9;
  padding: 0 8px;
  font-size: 10px;
}

.editor-viewport {
  position: relative;
  min-width: 0;
  min-height: 0;
  background: #050b11;
}

.viewport-canvas {
  display: block;
  width: 100%;
  height: 100%;
  outline: none;
}

.viewport-toolbar,
.viewport-layers,
.viewport-loading {
  position: absolute;
  z-index: 3;
  border: 1px solid #214767;
  border-radius: 6px;
  background: rgb(6 20 32 / 88%);
  backdrop-filter: blur(5px);
}

.viewport-toolbar {
  top: 10px;
  left: 10px;
  display: flex;
  gap: 5px;
  padding: 5px;
}

.viewport-toolbar span {
  padding: 4px 7px;
  border-radius: 4px;
  background: #102940;
  color: #b2c7d9;
  font-size: 9px;
}

.viewport-layers {
  top: 10px;
  right: 10px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 9px;
}

.viewport-layers label {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #b1c4d5;
  font-size: 9px;
}

.viewport-layers label.muted {
  color: #506b83;
}

.viewport-layers .texture-cache-clear {
  margin-top: 3px;
  padding: 4px 6px;
  border: 1px solid #284b66;
  border-radius: 4px;
  background: #0a1a27;
  color: #89a8c0;
  font-size: 8px;
  cursor: pointer;
}

.viewport-layers .texture-cache-clear:disabled {
  cursor: default;
  opacity: 0.45;
}

.viewport-loading {
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%);
  padding: 7px 10px;
  color: #93bce4;
  font-size: 10px;
}

.inspector-heading {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 11px 12px;
  border-bottom: 1px solid #173650;
}

.inspector-heading strong {
  font-size: 12px;
}

.inspector-heading span {
  color: #66849e;
  font-size: 9px;
}

.inspector-hero {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px;
}

.inspector-hero > div:last-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.inspector-hero strong {
  overflow: hidden;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.inspector-hero span {
  color: #7894ad;
  font-size: 9px;
}

.object-symbol {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid #245476;
  border-radius: 8px;
  background: #0e2a40;
  color: #69b1ff;
  font-size: 17px;
  font-weight: 800;
}

.property-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: 0;
}

.property-list.dense {
  gap: 0;
  padding: 0 12px 12px;
}

.property-list div {
  display: grid;
  gap: 3px;
}

.property-list.dense div {
  grid-template-columns: 106px minmax(0, 1fr);
  gap: 8px;
  padding: 6px 0;
  border-bottom: 1px solid #102c43;
}

.property-list dt {
  color: #7895ad;
  font-size: 10px;
}

.property-list dd {
  margin: 0;
  overflow-wrap: anywhere;
  color: #d4e2ee;
  font-size: 10px;
}

.inspector-stack {
  padding-top: 3px;
}

.mesh-list,
.material-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 12px 12px;
}

.mesh-row,
.material-row {
  border: 1px solid #173a57;
  border-radius: 6px;
  background: #091b2a;
}

.mesh-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
  padding: 8px;
}

.mesh-row strong {
  overflow: hidden;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mesh-row span {
  color: #6b8aa4;
  font-size: 9px;
}

.material-row {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  gap: 8px;
  padding: 8px;
}

.material-swatch {
  width: 26px;
  height: 26px;
  border: 1px solid rgb(255 255 255 / 16%);
  border-radius: 4px;
}

.material-row > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.material-row strong {
  font-size: 10px;
}

.material-row span,
.material-row small {
  overflow: hidden;
  color: #6f8ca5;
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.inspector-empty {
  padding: 12px;
  border: 1px dashed #24415a;
  border-radius: 6px;
  color: #65829a;
  font-size: 10px;
}

.editor-statusbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 9px;
  border-top: 1px solid #173650;
  background: #081420;
  color: #6f8ba4;
  font-size: 9px;
}

.editor-statusbar span:last-child {
  display: flex;
  gap: 7px;
}

.editor-statusbar b {
  color: #254760;
}

@media (max-width: 1120px) {
  .editor-grid {
    grid-template-columns: 190px minmax(0, 1fr) 270px;
  }

  .home-grid {
    grid-template-columns: 1fr;
  }

  .setup-grid {
    grid-template-columns: 1fr;
  }
}


.secondary-action.active-mode {
  border-color: #ff8a1c;
  background: linear-gradient(180deg, #b85212, #82380f);
  color: #fff4e8;
}


.preview-warning {
  border: 1px solid #a7611c;
  background: #3b2411 !important;
  color: #ffc778 !important;
}

.tool.active {
  box-shadow: 0 0 0 1px rgb(83 160 255 / 24%);
}


.editor-save {
  min-width: 92px;
  height: 30px;
  padding: 0 13px;
  font-size: 10px;
}

.editor-save:disabled {
  opacity: 0.45;
}


.transform-inspector {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.transform-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  padding: 0 12px;
}

.transform-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
}

.transform-field span {
  color: #7895ad;
  font-size: 9px;
}

.transform-field input {
  width: 100%;
  min-width: 0;
  height: 28px;
  padding: 0 7px;
  border: 1px solid #1c4668;
  border-radius: 5px;
  outline: none;
  background: #071725;
  color: #dbe8f4;
  font: inherit;
  font-size: 10px;
}

.transform-field input:focus {
  border-color: #4b9cf4;
  box-shadow: 0 0 0 2px rgb(75 156 244 / 12%);
}

.transform-help {
  margin: 0 12px 12px;
  padding: 7px 8px;
  border: 1px solid #173a57;
  border-radius: 5px;
  background: #091b2a;
  color: #7895ad;
  font-size: 9px;
  line-height: 1.45;
}


.explorer-search {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.explorer-search input:not(:disabled) {
  border-color: #1b4566;
  background: #071725;
  color: #dbe8f4;
}

.explorer-search span {
  color: #67859f;
  font-size: 8px;
}

.explorer-object-list {
  display: flex;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 2px;
  overflow: auto;
  padding: 0 7px 8px;
}

.explorer-object {
  display: flex;
  width: 100%;
  min-width: 0;
  flex: 0 0 auto;
  flex-direction: column;
  gap: 2px;
  padding: 6px 7px;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  color: #bfd0df;
  text-align: left;
  cursor: pointer;
}

.explorer-object:hover {
  border-color: #193b56;
  background: #0a1d2c;
}

.explorer-object.active {
  border-color: #2b6da0;
  background: #0d2a40;
}

.explorer-object-name {
  overflow: hidden;
  font-size: 9px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
