                writer.Write(new byte[64]);

                writer.Write((byte)0x49);
                writer.Write((uint)1);
                writer.Write(new byte[14]);

                writer.Write((byte)0x26);
                writer.Write((ushort)1);
                writer.Write(new byte[44]);
                writer.Write((byte)0);

                writer.Write((byte)0x54);
                writer.Write((uint)0);

                writer.Write((byte)0x79);
