    [Fact]
    public void O3dGeometryReader_ReadsRenderableGeometry()
    {
        var path = Path.Combine(
            Path.GetTempPath(),
            $"mapstudio-o3d-geometry-{Guid.NewGuid():N}.o3d");

        try
        {
            using (var stream = File.Create(path))
            using (var writer = new BinaryWriter(stream))
            {
                writer.Write((byte)0x84);
                writer.Write((byte)0x19);
                writer.Write((byte)0x07);
                writer.Write((byte)0x01);
                writer.Write(uint.MaxValue);

                writer.Write((byte)0x17);
                writer.Write((uint)3);

                WriteVertex(writer, 0, 0, 0, 0, 0, 1, 0, 0);
                WriteVertex(writer, 1, 0, 0, 0, 0, 1, 1, 0);
                WriteVertex(writer, 0, 1, 0, 0, 0, 1, 0, 1);

                writer.Write((byte)0x49);
                writer.Write((uint)1);
                writer.Write((uint)0);
                writer.Write((uint)1);
                writer.Write((uint)2);
                writer.Write((ushort)0);
            }

            var geometry =
                new OmsiO3dGeometryReader()
                    .Read(path);

            Assert.True(geometry.IsLoaded);
            Assert.Null(geometry.ErrorCode);

            Assert.Equal(
                new float[]
                {
                    0, 0, 0,
                    1, 0, 0,
                    0, 0, 1
                },
                geometry.Positions);

            Assert.Equal(
                new float[]
                {
                    0, 1, 0,
                    0, 1, 0,
                    0, 1, 0
                },
                geometry.Normals);

            Assert.Equal(
                new float[]
                {
                    0, 1,
                    1, 1,
                    0, 0
                },
                geometry.Uvs);

            Assert.Equal(
                new uint[] { 2, 1, 0 },
                geometry.Indices);
        }
        finally
        {
            File.Delete(path);
        }
    }

