    private static void WriteVertex(
        BinaryWriter writer,
        float x,
        float y,
        float z,
        float nx,
        float ny,
        float nz,
        float u,
        float v)
    {
        writer.Write(x);
        writer.Write(y);
        writer.Write(z);
        writer.Write(nx);
        writer.Write(ny);
        writer.Write(nz);
        writer.Write(u);
        writer.Write(v);
    }

